class MemoizedRecursiveStrategy implements RodCuttingStrategy {

    @Override
    public RodCuttingSolution solve(RodCuttingProblem problem) {
        int n = problem.rodLength();
        int[] memo = new int[n + 1];
        int[] bestCut = new int[n + 1];
